'use strict';
const $ = id => document.getElementById(id);
const key = 'alpegos-blacksmith-weapons-v5';
const goldIcon = '<span class="gold-icon" role="img" aria-label="gold"></span>';
const gold = n => `<span class="gold-amount">${n.toLocaleString()} ${goldIcon}</span>`;
const signed = n => `${n > 0 ? '+' : n < 0 ? '−' : ''}${gold(Math.abs(n))}`;
const cashDisplay = $('cash');
const floatingBalance = $('floating-balance');
function syncFloatingBalance() {
  const hidden = cashDisplay.getBoundingClientRect().bottom > 0;
  if (floatingBalance.hidden !== hidden) floatingBalance.hidden = hidden;
}
let state = Blacksmith.createGame(), servingCustomers = false;
let savedSnapshot = null;
try {
  savedSnapshot = localStorage.getItem(key);
  const restored = Blacksmith.migrateSave(JSON.parse(savedSnapshot || localStorage.getItem('alpegos-blacksmith-weapons-v4') || localStorage.getItem('alpegos-blacksmith-weapons-v3') || localStorage.getItem('alpegos-blacksmith-weapons-v2') || localStorage.getItem('alpegos-blacksmith-v1')));
  if (restored) state = restored;
} catch {}
function persist() {
  try {
    const next = JSON.stringify(state);
    localStorage.setItem(key, next);
    savedSnapshot = next;
  } catch {}
}
function withCurrentSave(change, messageId) {
  const apply = () => {
    if (servingCustomers) return;
    let latest;
    try { latest = localStorage.getItem(key); } catch { change(); return; }
    if (latest === savedSnapshot) { change(); return; }

    let restored;
    try { restored = Blacksmith.migrateSave(JSON.parse(latest)); } catch {}
    if (restored) {
      state = restored;
      savedSnapshot = latest;
      ShopCustomers.reset();
      render();
    }
    $(messageId).textContent = restored
      ? 'Another tab changed this shop. The latest save is loaded. Review it before trying again.'
      : 'The save changed in another tab. Reload this page before continuing.';
  };
  if (navigator.locks) {
    // Check and save under the same lock so simultaneous clicks cannot overwrite each other.
    navigator.locks.request(key, apply).catch(() => {
      $(messageId).textContent = 'Could not access the game save. Try again.';
    });
  } else {
    apply();
  }
}
function resetPlan() {
  const p = Blacksmith.blankPlan();
  $('weapon-plans').innerHTML = Blacksmith.weapons.map(w => `<div class="weapon-plan-row"><div class="weapon-info"><span class="weapon-icon">${w.icon}</span><div><strong>${w.name}</strong><span id="craft-info-${w.id}">${gold(w.cost)} to craft · market ${gold(w.price)}</span><span id="inventory-${w.id}"></span></div></div><label for="quantity-${w.id}">Craft<input id="quantity-${w.id}" aria-label="${w.name} quantity to craft" type="number" inputmode="numeric" min="0" max="40" step="1" value="${p.weapons[w.id].quantity}" required></label><label for="price-${w.id}"><span>Price ${goldIcon}</span><input id="price-${w.id}" aria-label="${w.name} price in gold" type="number" inputmode="numeric" min="1" max="100" step="1" value="${w.price}" required></label></div>`).join('');
  $('advertising').value = p.advertising;
}
function plan() { return { weapons: Object.fromEntries(Blacksmith.weapons.map(w => [w.id, { quantity: $(`quantity-${w.id}`).valueAsNumber, price: $(`price-${w.id}`).valueAsNumber }])), advertising: $('advertising').valueAsNumber }; }
function lockInputs(disabled) {
  Blacksmith.weapons.forEach(w => ['quantity', 'price'].forEach(k => { $(`${k}-${w.id}`).disabled = disabled; }));
  $('advertising').disabled = disabled;
}
function budget() {
  const p = plan(), craftCost = Blacksmith.planCost(p, state), cost = craftCost + p.advertising;
  $('craft-cost').innerHTML = Number.isFinite(craftCost) ? gold(craftCost) : '—';
  $('ad-cost').innerHTML = Number.isFinite(p.advertising) ? gold(p.advertising) : '—';
  $('investment').innerHTML = Number.isFinite(cost) ? gold(cost) : '—';
  const error = Blacksmith.validate(state, p);
  $('validation').textContent = state.history.length === 30 ? '' : error;
  $('open-shop').disabled = servingCustomers || Boolean(error);
}
const points = n => `${n > 0 ? '+' : ''}${n} pts`;
const demandEffect = score => {
  const percent = Math.round((Blacksmith.satisfactionMultiplier(score) - 1) * 1000) / 10;
  return `${percent > 0 ? '+' : ''}${percent}% demand`;
};
function renderUpgrades() {
  const finished = state.history.length === 30;
  $('upgrade-count').textContent = `${state.upgrades.length + state.forgeBaseLevel - 1} / 7 LEVELS INSTALLED`;
  $('upgrade-grid').innerHTML = Blacksmith.upgrades.map(u => {
    const level = Blacksmith.upgradeLevel(state, u.id), maxLevel = u.maxLevel || 1;
    const installed = level === maxLevel, disabled = installed || finished || servingCustomers || state.cash < u.cost;
    const displayLevel = level - (u.id === 'forge' ? 1 : 0);
    const displayMax = maxLevel - (u.id === 'forge' ? 1 : 0);
    const progress = maxLevel > 1 ? ` · Level ${displayLevel}` : '';
    const dots = maxLevel > 1 ? `<span class="upgrade-level-dots" aria-hidden="true">${Array.from({ length: displayMax }, (_, i) => i + 1).map(dot => `<span class="upgrade-level-dot${dot <= displayLevel ? ' filled' : ''}"></span>`).join('')}</span>` : '';
    const benefit = u.id === 'anvil' ? ` Current reduction: ${level} gold per weapon.` : u.id === 'forge' ? ` Current limit: ${level * 20} weapons per day.` : '';
    return `<article class="upgrade-item${installed ? ' installed' : ''}"><span class="upgrade-icon" aria-hidden="true">${u.icon}</span><h3>${u.name}${progress}</h3>${dots}<p>${u.description}${benefit}</p><button class="upgrade-buy" type="button" data-upgrade="${u.id}" ${disabled ? 'disabled' : ''}>${installed ? '✓ Installed · Max level' : finished ? 'Season complete' : servingCustomers ? 'Shop is open' : state.cash < u.cost ? `${gold(u.cost)} · Need ${gold(u.cost - state.cash)}` : `${maxLevel > 1 ? `Buy level ${displayLevel + 1} for` : 'Buy for'} ${gold(u.cost)} →`}</button></article>`;
  }).join('');
  const spent = state.purchases.reduce((total, p) => total + p.cost, 0);
  $('upgrade-spending').innerHTML = `Workshop investments · ${gold(spent)} spent`;
  $('upgrade-ledger').innerHTML = state.purchases.length ? state.purchases.map((p, i) => `<div><span>Before day ${p.afterDay + 1} · ${Blacksmith.upgrades.find(u => u.id === p.id).name}${['anvil', 'forge'].includes(p.id) ? ` · Level ${state.purchases.slice(0, i + 1).filter(item => item.id === p.id).length + (p.id === 'forge' ? state.forgeBaseLevel - 1 : 0)}` : ''}</span><strong>−${gold(p.cost)}</strong></div>`).join('') : 'No upgrades purchased yet.';
  const effect = Blacksmith.effects(state);
  $('capacity-hint').textContent = `${effect.capacity} weapons total per day · prices in gold`;
  $('ad-hint').textContent = effect.adReach > 1 ? 'Paid ads count as 50% more spending' : 'Promote every weapon in your shop';
  Blacksmith.weapons.forEach(w => {
    $(`quantity-${w.id}`).max = effect.capacity;
    $(`craft-info-${w.id}`).innerHTML = `${gold(Blacksmith.unitCost(state, w))} to craft · market ${gold(w.price)}`;
  });
}
function satisfactionReport(report) {
  const s = report.satisfaction;
  if (!s) return '<p class="report-note">Satisfaction was not tracked on this day.</p>';
  const offered = report.items.some(item => item.sold + item.stock > 0);
  const priceReason = s.model && !offered ? 'No prices evaluated'
    : s.priceEffect > 0 ? 'Good value compared with market prices' : s.priceEffect < 0 ? 'Prices above market value' : 'Prices balanced around market value';
  const inventoryReason = s.demand ? `${s.demand - s.unmetDemand} of ${s.demand} requests filled${s.model ? ' for weapons you offered' : ''}; ${s.unmetDemand} unmet`
    : s.model && !offered ? 'No weapons were offered' : 'No demand for the weapons on offer';
  const limited = s.change !== s.priceEffect + s.inventoryEffect ? ' Score capped at 0–100.' : '';
  return `<section class="satisfaction-report" aria-label="Day ${report.day} customer satisfaction"><strong>Customer satisfaction: ${s.score}/100 (${points(s.change)})</strong><p>${priceReason}: ${points(s.priceEffect)}.</p><p>${inventoryReason}: ${points(s.inventoryEffect)}.</p><p>${s.before} → ${s.score}.${limited}</p><p>${report.day === 30 ? 'Season complete; no further customer visits.' : `Expected demand tomorrow: ${demandEffect(s.score)} from satisfaction. Market conditions, prices and advertising also apply.`}</p></section>`;
}
function ledgerRow(kind, values) {
  const labels = ['Day', 'Weapon', 'Crafted', 'Sold', 'Price', 'Revenue', 'Expenses', 'Profit', kind === 'ledger-item' ? 'Stock' : 'Cash'];
  const cells = values.map((value, index) => {
    const content = typeof value === 'string' ? { text: value } : value;
    const className = content.className ? ` class="${content.className}"` : '';
    return `<td role="cell"${className}><span class="mobile-ledger-label" aria-hidden="true">${labels[index]}</span>${content.text}</td>`;
  }).join('');
  return `<tr role="row" class="${kind}">${cells}</tr>`;
}
function renderLedger() {
  $('ledger-count').textContent = `${state.history.length} day${state.history.length === 1 ? '' : 's'} in business`;
  $('ledger-body').innerHTML = state.history.length ? [...state.history].reverse().map(report => {
    const summary = ledgerRow('ledger-summary', [
      `<span class="day-chip">${String(report.day).padStart(2, '0')}</span>`, 'All weapons',
      String(report.quantity), String(report.sold), '—', gold(report.revenue), gold(report.expenses),
      { text: signed(report.profit), className: report.profit < 0 ? 'negative' : 'positive' },
      `<strong>${gold(report.cash)}</strong>`
    ]);
    const details = report.items.filter(item => item.quantity || item.sold || item.stock).map(item => {
      const weapon = Blacksmith.weapons.find(w => w.id === item.weapon);
      return ledgerRow('ledger-item', ['', `${weapon.icon} ${weapon.name}`,
        String(item.quantity), String(item.sold), gold(item.price), gold(item.revenue),
        `${gold(item.craftingCost)} craft`, '—', `${item.stock} left`]);
    }).join('');
    return summary + details;
  }).join('') : '<tr role="row"><td role="cell" colspan="9" class="empty-ledger">A fresh ledger, a fresh start. Your story begins on day one.</td></tr>';
}

function render() {
  const done = state.history.length === 30, last = state.history.at(-1);
  const bankrupt = !done && Blacksmith.isBankrupt(state);
  const balance = gold(state.cash);
  cashDisplay.innerHTML = balance;
  $('floating-cash').innerHTML = balance;
  $('stock').textContent = Blacksmith.totalStock(state.stock);
  $('satisfaction').textContent = `${state.satisfaction}/100`;
  $('satisfaction-note').textContent = done || bankrupt ? 'Final satisfaction' : `${demandEffect(state.satisfaction)} today`;
  Blacksmith.weapons.forEach(w => { $(`inventory-${w.id}`).textContent = `${state.stock[w.id]} in stock`; });
  $('profit').innerHTML = signed(state.cash - 100);
  $('profit').className = state.cash < 100 ? 'negative' : 'positive';
  $('day').innerHTML = `Day ${done ? 30 : state.history.length + 1} <small>/ 30</small>`;
  $('day-progress').style.width = `${state.history.length / 30 * 100}%`;
  $('plan-day').textContent = done ? '30 DAYS · THE JOURNEY IS COMPLETE' : `DAY ${String(state.history.length + 1).padStart(2, '0')} · THE WORKSHOP`;
  $('phase').textContent = bankrupt ? 'SHOP CLOSED' : done ? 'SEASON COMPLETE' : 'READY TO FORGE';
  $('market-title').textContent = bankrupt ? 'The shop is bankrupt' : done ? 'A month of fire and steel' : Blacksmith.markets[state.market].title;
  $('market-copy').textContent = bankrupt ? 'You have no stock and cannot afford to craft a weapon. Select New game to try again.'
    : done ? 'Your final cash is in. Start a new shop to try a different strategy.' : Blacksmith.markets[state.market].copy;
  lockInputs(done || bankrupt);
  $('open-shop').innerHTML = bankrupt ? 'Shop closed' : done ? '30 days complete <span>✓</span>' : 'Open shop & finish day <span>→</span>';
  if (last) {
    $('result-label').textContent = done ? 'YOUR 30-DAY STORY' : `DAY ${String(last.day).padStart(2, '0')} · THE EVENING REPORT`;
    $('result-heading').textContent = done ? 'The final hammer falls.' : last.profit > 0 ? 'A good day at the forge.' : last.profit < 0 ? 'A lesson at the forge.' : 'An even day at the forge.';
    $('result-content').className = 'filled-report';
    const rating = state.cash >= 1500 ? 'Master of the forge' : state.cash >= 500 ? 'A flourishing blacksmith' : state.cash > 100 ? 'A promising apprentice' : 'Every master starts somewhere';
    const breakdown = last.items.map((item, i) => `<div><span>${Blacksmith.weapons[i].icon} ${Blacksmith.weapons[i].name}</span><span>${item.sold} sold · ${item.stock} left</span><strong>${gold(item.revenue)}</strong></div>`).join('');
    $('result-content').innerHTML = `${done ? `<div class="final-banner"><span>✦ ${rating}</span><strong>${gold(state.cash)}</strong><p>Final cash · ${state.history.reduce((n,r) => n+r.sold,0)} weapons sold in 30 days</p></div>` : `<div class="sold-hero"><strong>${last.sold}<small> / ${last.sold + last.stock}</small></strong><span>WEAPONS SOLD</span></div>`}<div class="weapon-sales">${breakdown}</div>${satisfactionReport(last)}<div class="report-rows"><div><span>${done ? 'Day 30 revenue' : 'Sales revenue'}</span><strong>${gold(last.revenue)}</strong></div><div><span>Crafting expenses</span><strong>−${gold(last.craftingCost)}</strong></div><div><span>Advertising expenses</span><strong>−${gold(last.advertising)}</strong></div><div class="report-total"><span>Total expenses</span><strong>${gold(last.expenses)}</strong></div><div class="profit-row"><span>Day ${last.day} profit</span><strong class="${last.profit < 0 ? 'negative' : 'positive'}">${signed(last.profit)}</strong></div><div><span>Remaining cash</span><strong>${gold(last.cash)}</strong></div></div><p class="report-note">${done ? `${last.stock} unsold weapons remain. Final score is based on cash; stock is not liquidated.` : last.stock ? `${last.stock} unsold weapons saved for tomorrow. Adjust each weapon’s price to find its buyers.` : last.sold ? 'Sold out! Consider changing your weapon mix or raising prices tomorrow.' : 'No sales today. Try lowering prices or spreading the word.'}</p>`;
  } else {
    $('result-label').textContent = 'THE EVENING REPORT'; $('result-heading').textContent = 'Every blade has a beginning.';
    $('result-content').className = 'empty-report';
    $('result-content').innerHTML = '<div class="empty-icon">⚒</div><h3>The forge is waiting.</h3><p>Choose your weapon mix and open the shop.<br>Your daily results will appear here.</p><div class="tip"><span>✧</span><p><strong>A word from Alpego</strong>Swords sell for more, but daggers are cheaper to make. Mix your stock and watch which weapons sell.</p></div>';
  }
  renderLedger();
  $('mobile-next-plan').hidden = !last || done || bankrupt;
  if (bankrupt) {
    $('result-label').textContent = 'SHOP CLOSED';
    $('result-heading').textContent = 'The shop is bankrupt.';
    const reportNote = $('result-content').querySelector(':scope > .report-note:last-child');
    if (last) {
      $('result-content').querySelector('.satisfaction-report > p:last-child')?.remove();
      if (reportNote) reportNote.textContent = $('market-copy').textContent;
    } else {
      $('result-content').textContent = $('market-copy').textContent;
    }
  }
  renderUpgrades(); budget(); syncFloatingBalance();
}
$('upgrade-grid').addEventListener('click', e => {
  const button = e.target.closest('[data-upgrade]');
  if (!button || button.disabled || servingCustomers) return;
  const id = button.dataset.upgrade;
  withCurrentSave(() => {
    const error = Blacksmith.upgradeError(state, id);
    if (error) { $('upgrade-status').textContent = error; return; }
    state = Blacksmith.purchaseUpgrade(state, id);
    persist();
    $('upgrade-status').textContent = `${Blacksmith.upgrades.find(u => u.id === id).name}${['anvil', 'forge'].includes(id) ? ` level ${Blacksmith.upgradeLevel(state, id) - (id === 'forge' ? 1 : 0)}` : ''} installed. The benefit starts with your next batch. Its cost is recorded in Workshop investments and total profit.`;
    render();
  }, 'upgrade-status');
});
$('plan-form').addEventListener('input', budget);
$('plan-form').addEventListener('submit', e => {
  e.preventDefault(); if (servingCustomers) return;
  withCurrentSave(() => {
    const error = Blacksmith.validate(state, plan()); if (error) { $('validation').textContent = error; return; }
    state = Blacksmith.finishDay(state, plan()); persist();
    $('satisfaction').textContent = `${state.satisfaction}/100`;
    $('satisfaction-note').textContent = `${points(state.history.at(-1).satisfaction.change)} on day ${state.history.length}`; servingCustomers = true; renderUpgrades();
    lockInputs(true); $('restart-button').disabled = true; $('open-shop').disabled = true;
    $('phase').textContent = 'SHOP OPEN'; $('open-shop').innerHTML = 'Serving customers… <span>⚒</span>';
    $('result-label').textContent = `DAY ${state.history.length} · SHOP OPEN`; $('result-heading').textContent = 'Adventures start at your counter.';
    $('result-content').className = 'empty-report'; $('result-content').innerHTML = '<div class="empty-icon">⚔</div><h3>Steel, smiles, and a little gold.</h3><p>Customers are visiting the shop above.<br>Your evening report is on its way.</p>';
    ShopCustomers.play(state.history.at(-1), () => {
      servingCustomers = false;
      $('restart-button').disabled = false;
      render();
      if (matchMedia('(max-width: 680px)').matches) $('evening-report').scrollIntoView({ block: 'start' });
    });
  }, 'validation');
});
$('skip-customers').addEventListener('click', ShopCustomers.finish);
$('help-button').addEventListener('click', () => $('help-dialog').showModal());
document.querySelector('.dialog-close').addEventListener('click', () => $('help-dialog').close());
$('help-done').addEventListener('click', () => $('help-dialog').close());
$('restart-button').addEventListener('click', () => { $('restart-status').textContent = ''; $('restart-dialog').showModal(); });
$('cancel-restart').addEventListener('click', () => $('restart-dialog').close());
$('confirm-restart').addEventListener('click', () => withCurrentSave(() => {
  ShopCustomers.reset();
  state = Blacksmith.createGame();
  persist();
  resetPlan();
  $('upgrade-status').textContent = 'Choose an upgrade when your shop can afford it.';
  $('restart-dialog').close();
  render();
}, 'restart-status'));
resetPlan(); render();
window.addEventListener('scroll', syncFloatingBalance, { passive: true });
window.addEventListener('resize', syncFloatingBalance);

// Real CC0 hammer-on-anvil recording by VishwaJai (see assets/audio/CREDITS.md).
(() => {
  let audio, strikeBuffer;
  // Embed the local PCM recording so direct HTML playback needs no fetch or server change.
  const strikePCM = atob('');
  const pressSound = event => {
    if (event.type === 'pointerdown' && event.button !== 0) return;
    if (event.type === 'keydown' && (event.repeat || !['Enter', ' '].includes(event.key))) return;
    const button = event.target.closest('button');
    if (!event.isTrusted || !button || button.disabled || button.getAttribute('aria-disabled') === 'true') return;
    const Audio = window.AudioContext || window.webkitAudioContext;
    if (!Audio) return;
    try {
      audio ||= new Audio({ latencyHint: 'interactive' });
      const tap = () => {
        if (audio.state !== 'running') return;
        const start = audio.currentTime;
        if (!strikeBuffer) {
          strikeBuffer = audio.createBuffer(1, strikePCM.length / 2, 44100);
          const samples = strikeBuffer.getChannelData(0);
          for (let i = 0; i < samples.length; i++) {
            const value = strikePCM.charCodeAt(i * 2) | (strikePCM.charCodeAt(i * 2 + 1) << 8);
            samples[i] = (value >= 32768 ? value - 65536 : value) / 32768;
          }
        }
        const strike = audio.createBufferSource(), gain = audio.createGain(), filter = audio.createBiquadFilter();
        strike.buffer = strikeBuffer;
        filter.type = 'lowpass'; filter.frequency.value = 1400; filter.Q.value = .5;
        gain.gain.setValueAtTime(0, start);
        gain.gain.linearRampToValueAtTime(.12, start + .008);
        gain.gain.exponentialRampToValueAtTime(.0001, start + .16);
        gain.gain.linearRampToValueAtTime(0, start + .18);
        strike.connect(filter); filter.connect(gain); gain.connect(audio.destination);
        strike.onended = () => { strike.disconnect(); filter.disconnect(); gain.disconnect(); };
        strike.start(start);
        strike.stop(start + .19);
      };
      if (audio.state === 'running') tap();
      else audio.resume().then(tap).catch(() => {});
    } catch { /* Audio support must never interrupt the game controls. */ }
  };
  document.addEventListener('pointerdown', pressSound, true);
  document.addEventListener('keydown', pressSound, true);
  // Enter in a planning input can open shop without pressing a button first.
  document.addEventListener('submit', event => {
    if (!event.isTrusted || event.target.id !== 'plan-form') return;
    const Audio = window.AudioContext || window.webkitAudioContext;
    if (!Audio) return;
    try {
      audio ||= new Audio({ latencyHint: 'interactive' });
      if (audio.state !== 'running') audio.resume().catch(() => {});
    } catch {}
  }, true);
  document.addEventListener('shop-purchase', () => {
    if (!audio || audio.state !== 'running') return;
    try {
      const start = audio.currentTime;
      const tone = audio.createOscillator(), gain = audio.createGain();
      tone.type = 'sine';
      tone.frequency.setValueAtTime(1100, start);
      tone.frequency.exponentialRampToValueAtTime(650, start + .025);
      gain.gain.setValueAtTime(0, start);
      gain.gain.linearRampToValueAtTime(.035, start + .002);
      gain.gain.exponentialRampToValueAtTime(.0001, start + .03);
      gain.gain.linearRampToValueAtTime(0, start + .035);
      tone.connect(gain); gain.connect(audio.destination);
      tone.onended = () => { tone.disconnect(); gain.disconnect(); };
      tone.start(start); tone.stop(start + .04);
    } catch { /* Purchase feedback must never interrupt the customer scene. */ }
  });
})();
